INSERT INTO `t_article` VALUES (1818533708472369153, '不能说的秘密', '周杰伦', '最热', NULL, '最美的不是下雨天 是曾与你躲过雨的屋檐', '<p>最美的不是下雨天</p><p style=\"text-align: center;\">是曾与你躲过雨的屋檐</p><p style=\"text-align: center;\">回忆的画面 在荡着秋千</p><p style=\"text-align: center;\">梦开始不甜</p><p style=\"text-align: center;\">你说把爱渐渐放下会走更远</p><p style=\"text-align: center;\">又何必去改变 已错过的时间</p><p style=\"text-align: center;\">你用你的指尖阻止我说再见</p><p style=\"text-align: center;\">想象你在身边 在完全失去之前</p><p style=\"text-align: center;\">你说把爱渐渐放下会走更远</p><p style=\"text-align: center;\">或许命运的签 只让我们遇见</p><p style=\"text-align: center;\">只让我们相恋这一季的秋天</p><p style=\"text-align: center;\">飘落后才发现 这幸福的碎片</p><p>要我怎么捡</p>', NULL, 1, 1, -1, 1787722419869433858, 1787722419869433858, '2024-07-31 14:26:38', '2024-07-31 14:54:10', 0);
INSERT INTO `t_article` VALUES (1820718700405297153, '晴天', '周杰伦', '最新', NULL, '从前从前有个人爱你很久', '<p style=\"text-align: center;\">从前从前有个人爱你很久</p><p style=\"text-align: center;\">但偏偏风渐渐把距离吹得好远</p><p style=\"text-align: center;\">好不容易又能再多爱一天</p><p style=\"text-align: center;\">但故事的最后你好像还是说了拜拜</p><p style=\"text-align: center;\">为你翘课的那一天</p><p style=\"text-align: center;\">花落的那一天</p><p style=\"text-align: center;\">教室的那一间</p><p style=\"text-align: center;\">我怎么看不见</p><p style=\"text-align: center;\">消失的下雨天</p><p style=\"text-align: center;\">我好想再淋一遍</p><p style=\"text-align: center;\">没想到失去的勇气我还留着</p><p style=\"text-align: center;\">好想再问一遍</p><p style=\"text-align: center;\">你会等待还是离开</p><p style=\"text-align: center;\">刮风这天我试过握着你手</p><p style=\"text-align: center;\">但偏偏雨渐渐大到我看你不见</p><p style=\"text-align: center;\">还要多久我才能在你身边</p><p style=\"text-align: center;\">等到放晴的那天也许我会比较好一点</p><p style=\"text-align: center;\">从前从前有个人爱你很久</p><p style=\"text-align: center;\">偏偏风渐渐把距离吹得好远</p><p style=\"text-align: center;\">好不容易又能再多爱一天</p><p style=\"text-align: center;\">但故事的最后你好像还是说了拜拜</p><p style=\"text-align: center;\">刮风这天我试过握着你手</p><p style=\"text-align: center;\">但偏偏雨渐渐大到我看你不见</p><p style=\"text-align: center;\">还要多久我才能够在你身边</p><p style=\"text-align: center;\">等到放晴那天也许我会比较好一点</p><p style=\"text-align: center;\">从前从前有个人爱你很久</p><p style=\"text-align: center;\">但偏偏雨渐渐把距离吹得好远</p><p style=\"text-align: center;\">好不容易又能再多爱一天</p><p style=\"text-align: center;\">但故事的最后你好像还是说了拜</p>', NULL, 3, 1, -1, 1787722419869433858, 1787722419869433858, '2024-08-06 15:09:00', '2024-08-06 15:13:47', 0);
INSERT INTO `t_article` VALUES (1820722045182353409, '七里香', '周杰伦', '最新', NULL, '窗外的麻雀在电线杆上多嘴', '<p style=\"text-align: center;\">窗外的麻雀在电线杆上多嘴</p><p style=\"text-align: center;\">你说这一句很有夏天的感觉</p><p style=\"text-align: center;\">手中的铅笔在纸上来来回回</p><p style=\"text-align: center;\">我用几行字形容你是我的谁</p><p style=\"text-align: center;\">秋刀鱼的滋味猫跟你都想了解</p><p style=\"text-align: center;\">初恋的香味就这样被我们寻回</p><p style=\"text-align: center;\">那温暖的阳光像刚摘的鲜艳草莓</p><p style=\"text-align: center;\">你说你舍不得吃掉这一种感觉</p><p style=\"text-align: center;\">雨下整夜我的爱溢出就像雨水</p><p style=\"text-align: center;\">院子落叶跟我的思念厚厚一叠</p><p style=\"text-align: center;\">几句是非也无法将我的热情冷却</p><p style=\"text-align: center;\">你出现在我诗的每一页</p><p style=\"text-align: center;\">雨下整夜我的爱溢出就像雨水</p><p style=\"text-align: center;\">窗台蝴蝶像诗里纷飞的美丽章节</p><p style=\"text-align: center;\">我接着写</p><p style=\"text-align: center;\">把永远爱你写进诗的结尾</p><p style=\"text-align: center;\"><img src=\"http://localhost:8088/img/5c9bc77df5ab41e1850869203eacd4ce.jpg\" alt=\"\" data-href=\"\" style=\"width: 50%;\"></p><p style=\"text-align: center;\"><br></p>', NULL, 1, 1, 1, 1787722419869433858, 1787722419869433858, '2024-08-06 15:22:18', '2024-09-20 15:03:41', 0);
INSERT INTO `t_article` VALUES (1820722484686692353, '夜曲', '周杰伦', '最新', NULL, '一群嗜血的蚂蚁 被腐肉所吸引', '<p style=\"text-align: center;\">一群嗜血的蚂蚁 被腐肉所吸引</p><p style=\"text-align: center;\">我面无表情 看孤独的风景</p><p style=\"text-align: center;\">失去你 爱恨开始分明</p><p style=\"text-align: center;\">失去你 还有什么事好关心</p><p style=\"text-align: center;\">当鸽子不再象征和平</p><p style=\"text-align: center;\">我终于被提醒</p><p style=\"text-align: center;\">广场上喂食的是秃鹰</p><p style=\"text-align: center;\">我用漂亮的押韵</p><p style=\"text-align: center;\">形容被掠夺一空的爱情</p><p style=\"text-align: center;\">啊 乌云开始遮蔽 夜色不干净</p><p style=\"text-align: center;\">公园里 葬礼的回音 在漫天飞行</p><p style=\"text-align: center;\">送你的白色玫瑰</p><p style=\"text-align: center;\">在纯黑的环境凋零</p><p style=\"text-align: center;\">乌鸦在树枝上诡异的很安静</p><p style=\"text-align: center;\">静静听 我黑色的大衣</p><p style=\"text-align: center;\">想温暖你日渐冰冷的回忆</p><p style=\"text-align: center;\">走过的走过的生命</p><p style=\"text-align: center;\">啊 四周弥漫雾气</p><p style=\"text-align: center;\">啊 我在空旷的墓地</p><p style=\"text-align: center;\">老去后还爱你</p><p style=\"text-align: center;\">为你弹奏肖邦的夜曲</p><p style=\"text-align: center;\">纪念我死去的爱情</p>', NULL, 4, 1, -1, 1787722419869433858, 1787722419869433858, '2024-07-31 14:26:38', '2024-07-31 14:54:10', 0);
INSERT INTO `t_article` VALUES (1820723142772989954, '蒲公英的约定', '周杰伦', '最新', NULL, '一起长大的约定', '<p>一起长大的约定</p><p>那样清晰 打过勾的我相信</p><p>说好要一起旅行</p><p>是你如今 唯一坚持的任性</p><p>在走廊上罚站打手心</p><p>我们却注意窗边的蜻蜓</p><p><span style=\"color: rgb(85, 85, 85); font-size: 12px; font-family: 宋体;\"><sup><em>《蒲公英的约定》歌曲简谱 [2]</em></sup></span>我去到哪里你都跟很紧</p>', NULL, 5, 1, NULL, 1787722419869433858, 1787722419869433858, '2024-07-31 14:26:38', '2024-07-31 14:54:10', 0);
INSERT INTO `t_article` VALUES (1821368972454473729, '文章分页显示', 'zz', '最热', NULL, '文章分页列表', '<p>1.分页代码</p><p><br></p><pre><code class=\"language-java\"> /**\n     * 文章分页列表\n     *\n     * @param articleQuery\n     * @return\n     */\n    @Override\n    public IPage&lt;ArticleVO&gt; selectArticlePage(ArticleQuery articleQuery) {\n        LambdaQueryWrapper&lt;Article&gt; wrapper = new LambdaQueryWrapper&lt;&gt;();\n        if (StringUtils.isNotBlank(articleQuery.getTitle())) {\n            wrapper.like(Article::getTitle, articleQuery.getTitle());\n        }\n        if (StringUtils.isNotBlank(articleQuery.getCategoryName())) {\n            wrapper.like(Article::getCategoryName, articleQuery.getCategoryName());\n        }\n        if (articleQuery.getPublish() != null) {\n            wrapper.eq(Article::getPublish, articleQuery.getPublish());\n        }\n        wrapper.orderByAsc(Article::getSort);\n        IPage&lt;Article&gt; page = new Page&lt;&gt;(articleQuery.getPage(), articleQuery.getLimit());\n        IPage&lt;Article&gt; articlePage = this.page(page, wrapper);\n\n\n        IPage&lt;ArticleVO&gt; articleVOIPage = articlePage.convert(article -&gt; {\n            ArticleVO articleVO = this.convertToArticleVO(article);\n            return articleVO;\n        });\n\n        return articleVOIPage;\n    }</code></pre><p><br></p>', NULL, 9, -1, NULL, 1787722419869433858, 1787722419869433858, '2024-07-31 14:26:38', '2024-07-31 14:54:10', 0);
